import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy, PlacedTool, ToolShape } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    hasCommonLine: boolean; // Priority flag
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; 
    preferredRotation?: number; // 0 or 90
    aspectRatio: number; // max / min
}

interface PlacedPackerItem {
    item: PackerItem;
    x: number;
    y: number;
    width: number;
    height: number;
    rotation: number;
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
}

// ----------------------------------------------------------------------
// PRE-FLIGHT ANALYSIS
// ----------------------------------------------------------------------

const determineOptimalOrientation = (
    partW: number, 
    partH: number, 
    sheetW: number, 
    sheetH: number, 
    gapX: number, 
    gapY: number,
    canRotate: boolean
): number | undefined => {
    if (!canRotate) return 0;

    const calculateCapacity = (w: number, h: number) => {
        if (w > sheetW || h > sheetH) return 0;
        const cols = Math.floor((sheetW + gapX) / (w + gapX));
        const rows = Math.floor((sheetH + gapY) / (h + gapY));
        return cols * rows;
    };

    const count0 = calculateCapacity(partW, partH);
    const count90 = calculateCapacity(partH, partW);

    if (count90 > count0) return 90;
    if (count0 > count90) return 0;

    return sheetW > sheetH ? (partW > partH ? 0 : 90) : (partW > partH ? 90 : 0);
};

// ----------------------------------------------------------------------
// MAXIMAL RECTANGLES PACKER (MaxRects)
// ----------------------------------------------------------------------

class MaxRectsPacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: PlacedPackerItem[];
    parts: Part[];
    tools: Tool[];

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number,
        useCommonLine: boolean = false,
        parts: Part[],
        tools: Tool[]
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.parts = parts;
        this.tools = tools;
    }

    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, sX: number, sY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0;
        let bestSX = 0;
        let bestSY = 0;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Try 0 degrees ---
            {
                // Calculate Spacing
                const spacing = this.calculateSpacing(item, 0, rect);
                const effectiveW = item.width + spacing.x;
                const effectiveH = item.height + spacing.y;

                if (effectiveW <= rect.w && effectiveH <= rect.h) {
                    const leftoverX = rect.w - effectiveW;
                    const leftoverY = rect.h - effectiveH;
                    const shortSideFit = Math.min(leftoverX, leftoverY);
                    const longSideFit = Math.max(leftoverX, leftoverY);

                    let score = shortSideFit * 1000 + longSideFit;

                    // Bonus for Common Line usage (smaller spacing implies efficient packing)
                    if (spacing.x < this.spacingX || spacing.y < this.spacingY) score -= 5000;

                    const orientationBonus = (item.preferredRotation === 0) ? -500 : 0;

                    if ((score + orientationBonus) < bestScore) {
                        bestScore = score + orientationBonus;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSX = spacing.x;
                        bestSY = spacing.y;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const spacing = this.calculateSpacing(item, 90, rect);
                const effectiveW = item.rotatedWidth + spacing.x;
                const effectiveH = item.rotatedHeight + spacing.y;

                if (effectiveW <= rect.w && effectiveH <= rect.h) {
                    const leftoverX = rect.w - effectiveW;
                    const leftoverY = rect.h - effectiveH;
                    const shortSideFit = Math.min(leftoverX, leftoverY);
                    const longSideFit = Math.max(leftoverX, leftoverY);

                    let score = shortSideFit * 1000 + longSideFit;
                    if (spacing.x < this.spacingX || spacing.y < this.spacingY) score -= 5000;

                    const orientationBonus = (item.preferredRotation === 90) ? -500 : 0;

                    if ((score + orientationBonus) < bestScore) {
                        bestScore = score + orientationBonus;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSX = spacing.x;
                        bestSY = spacing.y;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { rectIndex: bestRectIndex, rotation: bestRotation, score: bestScore, sX: bestSX, sY: bestSY };
        }
        return null;
    }

    // Helper: Determine spacing based on neighbors
    private calculateSpacing(item: PackerItem, rotation: number, rect: FreeRect): { x: number, y: number } {
        let sX = this.spacingX;
        let sY = this.spacingY;

        if (rect.x === 0) sX = 0;
        if (rect.y === 0) sY = 0;

        if (this.useCommonLine || item.hasCommonLine) {
            const epsilon = 0.5;
            const candPart = this.parts.find(p => p.id === item.partId);

            if (candPart) {
                // --- X-AXIS COMMON LINE ---
                if (rect.x > 0) {
                    const neighbor = this.placedItems.find(p => 
                        Math.abs((p.x + p.width) - rect.x) < epsilon && 
                        Math.abs(p.y - rect.y) < epsilon
                    );

                    if (neighbor) {
                        const neighborPart = this.parts.find(p => p.id === neighbor.item.partId);
                        // 1. Geometric Check (Height Match)
                        const h = rotation === 90 ? item.rotatedHeight : item.height;
                        if (Math.abs(neighbor.height - h) < epsilon && neighborPart) {

                            // 2. Punch Analysis
                            const gap = this.solveCommonLineGap(
                                neighborPart, neighbor.rotation, 'right',
                                candPart, rotation, 'left'
                            );

                            if (gap !== null) sX = gap;
                        }
                    }
                }

                // --- Y-AXIS COMMON LINE ---
                if (rect.y > 0) {
                    const neighbor = this.placedItems.find(p => 
                        Math.abs((p.y + p.height) - rect.y) < epsilon && 
                        Math.abs(p.x - rect.x) < epsilon
                    );

                    if (neighbor) {
                        const neighborPart = this.parts.find(p => p.id === neighbor.item.partId);
                        const w = rotation === 90 ? item.rotatedWidth : item.width;
                        if (Math.abs(neighbor.width - w) < epsilon && neighborPart) {

                            const gap = this.solveCommonLineGap(
                                neighborPart, neighbor.rotation, 'top',
                                candPart, rotation, 'bottom'
                            );

                            if (gap !== null) sY = gap;
                        }
                    }
                }
            }
        }

        return { x: sX, y: sY };
    }

    private solveCommonLineGap(
        pA: Part, rotA: number, edgeA: 'right' | 'top',
        pB: Part, rotB: number, edgeB: 'left' | 'bottom'
    ): number | null {
        // Get relevant punches on the interface edges
        // A is Neighbor (Left/Top), B is Candidate (Right/Bottom)

        const getEdgeTool = (part: Part, rot: number, edge: 'left'|'right'|'top'|'bottom') => {
            // Normalize punch coords to World Space (assuming part at 0,0) based on rotation
            // We want the punch relative to the bounding box face.
            const w = part.geometry.width;
            const h = part.geometry.height;
            const tools = this.tools;

            let matches: { toolId: string, edgeOffset: number, rotation: number }[] = [];

            part.punches.forEach(p => {
                // Transform P to World (Part @ 0,0)
                let wx = p.x; 
                let wy = p.y;
                let dimX = w;
                let dimY = h;

                if (rot === 90) {
                    wx = -p.y + h; // 90 deg rotation transform mapping x->y axis roughly
                    wy = p.x;
                    dimX = h;
                    dimY = w;
                }

                // Check distance to requested edge
                const tool = tools.find(t => t.id === p.toolId);
                if (!tool) return;
                const r = tool.width / 2; // Assume symmetric or use logic

                let dist = Infinity;
                let offset = 0; // Positive = Inside part, Negative = Outside

                if (edge === 'right') { // x = dimX
                    dist = Math.abs(wx - dimX);
                    offset = wx - dimX; 
                } else if (edge === 'left') { // x = 0
                    dist = Math.abs(wx - 0);
                    offset = wx;
                } else if (edge === 'top') { // y = dimY
                    dist = Math.abs(wy - dimY);
                    offset = wy - dimY;
                } else if (edge === 'bottom') { // y = 0
                    dist = Math.abs(wy - 0);
                    offset = wy;
                }

                if (dist < (r + 1.0)) { // Within 1mm of edge + radius
                    matches.push({ toolId: p.toolId, edgeOffset: offset, rotation: p.rotation });
                }
            });

            // Prioritize rectangular tools for common cuts
            matches.sort((a,b) => a.edgeOffset - b.edgeOffset); // Just pick first for now
            return matches.length > 0 ? matches[0] : null;
        };

        const tA = getEdgeTool(pA, rotA, edgeA);
        const tB = getEdgeTool(pB, rotB, edgeB);

        if (tA && tB && tA.toolId === tB.toolId) {
            // Found matching tool used on both edges!
            const tool = this.tools.find(t => t.id === tA.toolId);
            if (!tool) return null;

            // Calculate the effective dimension of the tool in the direction of separation (perpendicular to cut)
            // This ensures we get the "Height" of the tool relative to the cut, to overlap fully.

            // Total Rotation relative to the nest = Part Rotation + Punch Rotation
            // (We use tA because we want the dimension of the tool as it cuts the edge of A)
            const totalRot = (rotA + tA.rotation) % 360;
            const rad = totalRot * Math.PI / 180;

            let tW = tool.width;
            let tH = tool.height;
            if (tool.shape === ToolShape.Circle) tH = tW;

            const absCos = Math.abs(Math.cos(rad));
            const absSin = Math.abs(Math.sin(rad));

            // Effective BBox of tool
            const effW = tW * absCos + tH * absSin;
            const effH = tW * absSin + tH * absCos;

            // Determine which dimension is the "separation" dimension
            // If cutting vertical line (edge Left/Right), we separate in X. We need X dimension.
            if (edgeA === 'right') {
                return -effW; // Negative Tool Width
            } else {
                // If cutting horizontal line (edge Top/Bottom), we separate in Y. We need Y dimension.
                return -effH; // Negative Tool Height
            }
        }

        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, sX: number, sY: number) {
        const freeRect = this.freeRects[rectIndex];

        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        // Position: FreeRect start + spacing
        const placedX = freeRect.x + sX;
        const placedY = freeRect.y + sY;

        // Add to placed list
        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            width: w,
            height: h,
            rotation
        });

        // "Used" Rectangle includes the spacing gap we consumed.
        // It starts at the FreeRect origin and extends to cover the part.
        const usedRect: FreeRect = {
            x: freeRect.x,
            y: freeRect.y,
            w: sX + w, // Consumes gap + part width
            h: sY + h  // Consumes gap + part height
        };

        // --- MAXRECTS SPLIT & PRUNE ---

        const newFreeRects: FreeRect[] = [];

        for (let i = 0; i < this.freeRects.length; i++) {
            const existing = this.freeRects[i];

            if (this.intersects(existing, usedRect)) {
                // Top
                if (usedRect.y > existing.y && usedRect.y < existing.y + existing.h) {
                    newFreeRects.push({
                        x: existing.x,
                        y: existing.y,
                        w: existing.w,
                        h: usedRect.y - existing.y
                    });
                }
                // Bottom
                if (usedRect.y + usedRect.h < existing.y + existing.h) {
                    newFreeRects.push({
                        x: existing.x,
                        y: usedRect.y + usedRect.h,
                        w: existing.w,
                        h: (existing.y + existing.h) - (usedRect.y + usedRect.h)
                    });
                }
                // Left
                if (usedRect.x > existing.x && usedRect.x < existing.x + existing.w) {
                    newFreeRects.push({
                        x: existing.x,
                        y: existing.y,
                        w: usedRect.x - existing.x,
                        h: existing.h
                    });
                }
                // Right
                if (usedRect.x + usedRect.w < existing.x + existing.w) {
                    newFreeRects.push({
                        x: usedRect.x + usedRect.w,
                        y: existing.y,
                        w: (existing.x + existing.w) - (usedRect.x + usedRect.w),
                        h: existing.h
                    });
                }
            } else {
                newFreeRects.push(existing);
            }
        }

        this.freeRects = newFreeRects;
        this.pruneFreeRects();
    }

    private intersects(a: FreeRect, b: FreeRect): boolean {
        return a.x < b.x + b.w && a.x + a.w > b.x &&
               a.y < b.y + b.h && a.y + a.h > b.y;
    }

    private pruneFreeRects() {
        this.freeRects = this.freeRects.filter(r => r.w > 0.5 && r.h > 0.5);

        for (let i = 0; i < this.freeRects.length; i++) {
            for (let j = 0; j < this.freeRects.length; j++) {
                if (i === j) continue;
                if (this.isContained(this.freeRects[i], this.freeRects[j])) {
                    this.freeRects.splice(i, 1);
                    i--; 
                    break; 
                }
            }
        }
    }

    private isContained(inner: FreeRect, outer: FreeRect): boolean {
        return inner.x >= outer.x && inner.y >= outer.y &&
               inner.x + inner.w <= outer.x + outer.w &&
               inner.y + inner.h <= outer.y + outer.h;
    }
}

// ----------------------------------------------------------------------
// ADAPTIVE GROUPING LOGIC
// ----------------------------------------------------------------------

enum PriorityGroup {
    BigLong = 0,
    SmallLong = 1,
    BigSquare = 2,
    SmallSquare = 3,
    Unknown = 99
}

const getGroupPriorityScore = (group: PriorityGroup): number => {
    switch (group) {
        case PriorityGroup.BigLong: return 4000;
        case PriorityGroup.SmallLong: return 3000;
        case PriorityGroup.BigSquare: return 2000;
        case PriorityGroup.SmallSquare: return 1000;
        default: return 0;
    }
};

const classifyItems = (items: PackerItem[]): { classifications: Map<string, PriorityGroup>, counts: Record<PriorityGroup, number>, medianArea: number } => {
    if (items.length === 0) return { classifications: new Map(), counts: {0:0,1:0,2:0,3:0,99:0} as any, medianArea: 0 };

    const areas = items.map(i => i.area).sort((a,b) => a - b);
    const mid = Math.floor(areas.length / 2);
    const medianArea = areas.length % 2 !== 0 ? areas[mid] : (areas[mid - 1] + areas[mid]) / 2;

    const classifications = new Map<string, PriorityGroup>();
    const counts: Record<PriorityGroup, number> = {
        [PriorityGroup.BigLong]: 0,
        [PriorityGroup.SmallLong]: 0,
        [PriorityGroup.BigSquare]: 0,
        [PriorityGroup.SmallSquare]: 0,
        [PriorityGroup.Unknown]: 0
    };

    items.forEach(item => {
        const isBig = item.area >= medianArea;
        const isLong = item.aspectRatio >= 1.5;

        let group: PriorityGroup;
        if (isBig && isLong) group = PriorityGroup.BigLong;
        else if (!isBig && isLong) group = PriorityGroup.SmallLong;
        else if (isBig && !isLong) group = PriorityGroup.BigSquare;
        else group = PriorityGroup.SmallSquare;

        classifications.set(item.uid, group);
        counts[group]++;
    });

    return { classifications, counts, medianArea };
};

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    const orientationPreferences = new Map<string, number>();

    const stockSheet = settings.availableSheets.find(s => s.id === settings.activeSheetId) || settings.availableSheets[0];
    const simW = stockSheet ? stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight : 2500;
    const simH = stockSheet ? stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom : 1250;

    const uniquePartIds = Array.from(new Set(scheduledParts.map(sp => sp.partId)));

    for (const pid of uniquePartIds) {
        const part = allParts.find(p => p.id === pid);
        const sched = scheduledParts.find(sp => sp.partId === pid);
        if (part && sched) {
            const dims = calculatePartPhysicalExtents(part, tools);
            const pref = determineOptimalOrientation(
                dims.width, dims.height, 
                simW, simH, 
                settings.partSpacingX, settings.partSpacingY,
                sched.nesting.allow90_270
            );
            if (pref !== undefined) {
                orientationPreferences.set(pid, pref);
            }
        }
    }

    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        const preferredRot = orientationPreferences.get(sp.partId);

        const maxDim = Math.max(dims0.width, dims0.height);
        const minDim = Math.min(dims0.width, dims0.height);
        const aspectRatio = minDim > 0 ? maxDim / minDim : 1;

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                hasCommonLine: sp.nesting.commonLine, // Propagate setting to item
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX,
                area: dims0.width * dims0.height,
                preferredRotation: preferredRot,
                aspectRatio
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    const calculateEfficiency = (packer: MaxRectsPacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    while (remainingItems.length > 0) {

        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        const { classifications, counts, medianArea } = classifyItems(remainingItems);
        const totalRemaining = remainingItems.length;
        const hasBigItems = (counts[PriorityGroup.BigLong] + counts[PriorityGroup.BigSquare]) > 0;

        const strategies: { name: string, packer: MaxRectsPacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Priority-Adaptive', sort: 'weighted_group' },
            { id: 'BestFit-Area', sort: 'area' },
            { id: 'MaxSide', sort: 'max_side' },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            currentItems.sort((a, b) => {
                if (config.sort === 'weighted_group') {
                    const groupA = classifications.get(a.uid) ?? PriorityGroup.Unknown;
                    const baseA = getGroupPriorityScore(groupA);
                    const ratioA = totalRemaining > 0 ? counts[groupA] / totalRemaining : 0;
                    const bonusA = ratioA * 500;
                    // INCREASE PRIORITY FOR COMMON LINE ITEMS
                    const scoreA = baseA + bonusA + (a.hasCommonLine ? 5000 : 0);

                    const groupB = classifications.get(b.uid) ?? PriorityGroup.Unknown;
                    const baseB = getGroupPriorityScore(groupB);
                    const ratioB = totalRemaining > 0 ? counts[groupB] / totalRemaining : 0;
                    const bonusB = ratioB * 500;
                    // INCREASE PRIORITY FOR COMMON LINE ITEMS
                    const scoreB = baseB + bonusB + (b.hasCommonLine ? 5000 : 0);

                    if (Math.abs(scoreA - scoreB) > 1) {
                        return scoreB - scoreA;
                    }
                    return b.area - a.area;
                }

                if (config.sort === 'width') return b.width - a.width;
                if (config.sort === 'max_side') return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                return b.area - a.area;
            });

            if (hasBigItems && config.sort === 'weighted_group') {
                // If the top item isn't common line, check if we need to pull big items.
                // If top item IS common line (score > 5000), leave it.
                if (!currentItems[0].hasCommonLine) {
                    const firstBigIndex = currentItems.findIndex(item => {
                        const g = classifications.get(item.uid);
                        return g === PriorityGroup.BigLong || g === PriorityGroup.BigSquare;
                    });

                    if (firstBigIndex > 0) {
                        const bigItem = currentItems[firstBigIndex];
                        currentItems.splice(firstBigIndex, 1);
                        currentItems.unshift(bigItem);
                    }
                }
            }

            // Pass Parts and Tools to Packer
            const packer = new MaxRectsPacker(packW, packH, partSpacingX, partSpacingY, useCommonLine, allParts, tools);
            const packedUids = new Set<string>();

            for (const item of currentItems) {
                const bestPos = packer.findPosition(item);
                if (bestPos) {
                    packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.sX, bestPos.sY);
                    packedUids.add(item.uid);
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            let score = count * 1000 + efficiency * 100;
            if (config.id === 'Priority-Adaptive') score += 50; 

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        const templateParts = winner.packer.placedItems;
        const requiredParts = new Map<string, number>();
        templateParts.forEach(p => {
            requiredParts.set(p.item.partId, (requiredParts.get(p.item.partId) || 0) + 1);
        });

        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        let sheetQuantity = 1;

        while (true) {
            const indicesToRemove: number[] = [];
            const tempUsedIndices = new Set<number>();
            let possible = true;

            for (const [partId, reqQty] of requiredParts.entries()) {
                let found = 0;
                for (let i = 0; i < remainingItems.length; i++) {
                    if (tempUsedIndices.has(i)) continue;
                    if (remainingItems[i].partId === partId) {
                        tempUsedIndices.add(i);
                        indicesToRemove.push(i);
                        found++;
                        if (found === reqQty) break;
                    }
                }
                if (found < reqQty) { possible = false; break; }
            }

            if (possible) {
                sheetQuantity++;
                indicesToRemove.sort((a, b) => b - a);
                indicesToRemove.forEach(idx => remainingItems.splice(idx, 1));
            } else {
                break;
            }
        }

        const packer = winner.packer;

        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = p.width; // Already resolved in placedItems
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1} (${winner.name})`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: sheetQuantity
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy, PlacedTool, ToolShape } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

enum PriorityGroup {
    BigLong = 0,
    SmallLong = 1,
    BigSquare = 2,
    SmallSquare = 3,
    Unknown = 99
}

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    hasCommonLine: boolean; // Priority flag
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; 
    preferredRotation?: number; // 0 or 90
    aspectRatio: number; // max / min
    currentGroup?: PriorityGroup;
}

interface PlacedPackerItem {
    item: PackerItem;
    x: number;
    y: number;
    width: number;
    height: number;
    rotation: number;
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
}

// ----------------------------------------------------------------------
// PRE-FLIGHT ANALYSIS
// ----------------------------------------------------------------------

const determineOptimalOrientation = (
    partW: number, 
    partH: number, 
    sheetW: number, 
    sheetH: number, 
    gapX: number, 
    gapY: number,
    canRotate: boolean
): number | undefined => {
    if (!canRotate) return 0;

    const calculateCapacity = (w: number, h: number) => {
        if (w > sheetW || h > sheetH) return 0;
        const cols = Math.floor((sheetW + gapX) / (w + gapX));
        const rows = Math.floor((sheetH + gapY) / (h + gapY));
        return cols * rows;
    };

    const count0 = calculateCapacity(partW, partH);
    const count90 = calculateCapacity(partH, partW);

    if (count90 > count0) return 90;
    if (count0 > count90) return 0;

    return sheetW > sheetH ? (partW > partH ? 0 : 90) : (partW > partH ? 90 : 0);
};

// ----------------------------------------------------------------------
// MAXIMAL RECTANGLES PACKER (MaxRects)
// ----------------------------------------------------------------------

class MaxRectsPacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: PlacedPackerItem[];
    parts: Part[];
    tools: Tool[];

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number,
        useCommonLine: boolean = false,
        parts: Part[],
        tools: Tool[]
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.parts = parts;
        this.tools = tools;
    }

    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, sX: number, sY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0;
        let bestSX = 0;
        let bestSY = 0;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Try 0 degrees ---
            {
                // Calculate Spacing
                const spacing = this.calculateSpacing(item, 0, rect);
                const effectiveW = item.width + spacing.x;
                const effectiveH = item.height + spacing.y;

                if (effectiveW <= rect.w && effectiveH <= rect.h) {
                    const leftoverX = rect.w - effectiveW;
                    const leftoverY = rect.h - effectiveH;
                    const shortSideFit = Math.min(leftoverX, leftoverY);
                    const longSideFit = Math.max(leftoverX, leftoverY);

                    let score = shortSideFit * 1000 + longSideFit;

                    // Bonus for Common Line usage (smaller spacing implies efficient packing)
                    if (spacing.x < this.spacingX || spacing.y < this.spacingY) score -= 5000;

                    const orientationBonus = (item.preferredRotation === 0) ? -500 : 0;

                    // Priority Bonus for SmallLong items at 0 degrees
                    const groupBonus = (item.currentGroup === PriorityGroup.SmallLong) ? -2000 : 0;

                    if ((score + orientationBonus + groupBonus) < bestScore) {
                        bestScore = score + orientationBonus + groupBonus;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSX = spacing.x;
                        bestSY = spacing.y;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const spacing = this.calculateSpacing(item, 90, rect);
                const effectiveW = item.rotatedWidth + spacing.x;
                const effectiveH = item.rotatedHeight + spacing.y;

                if (effectiveW <= rect.w && effectiveH <= rect.h) {
                    const leftoverX = rect.w - effectiveW;
                    const leftoverY = rect.h - effectiveH;
                    const shortSideFit = Math.min(leftoverX, leftoverY);
                    const longSideFit = Math.max(leftoverX, leftoverY);

                    let score = shortSideFit * 1000 + longSideFit;
                    if (spacing.x < this.spacingX || spacing.y < this.spacingY) score -= 5000;

                    const orientationBonus = (item.preferredRotation === 90) ? -500 : 0;

                    if ((score + orientationBonus) < bestScore) {
                        bestScore = score + orientationBonus;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSX = spacing.x;
                        bestSY = spacing.y;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { rectIndex: bestRectIndex, rotation: bestRotation, score: bestScore, sX: bestSX, sY: bestSY };
        }
        return null;
    }

    // Helper: Determine spacing based on neighbors
    private calculateSpacing(item: PackerItem, rotation: number, rect: FreeRect): { x: number, y: number } {
        let sX = this.spacingX;
        let sY = this.spacingY;

        if (rect.x === 0) sX = 0;
        if (rect.y === 0) sY = 0;

        if (this.useCommonLine || item.hasCommonLine) {
            const epsilon = 0.5;
            const candPart = this.parts.find(p => p.id === item.partId);

            if (candPart) {
                // --- X-AXIS COMMON LINE ---
                if (rect.x > 0) {
                    const neighbor = this.placedItems.find(p => 
                        Math.abs((p.x + p.width) - rect.x) < epsilon && 
                        Math.abs(p.y - rect.y) < epsilon
                    );

                    if (neighbor) {
                        const neighborPart = this.parts.find(p => p.id === neighbor.item.partId);
                        // 1. Geometric Check (Height Match)
                        const h = rotation === 90 ? item.rotatedHeight : item.height;
                        if (Math.abs(neighbor.height - h) < epsilon && neighborPart) {

                            // 2. Punch Analysis
                            const gap = this.solveCommonLineGap(
                                neighborPart, neighbor.rotation, 'right',
                                candPart, rotation, 'left'
                            );

                            if (gap !== null) sX = gap;
                        }
                    }
                }

                // --- Y-AXIS COMMON LINE ---
                if (rect.y > 0) {
                    const neighbor = this.placedItems.find(p => 
                        Math.abs((p.y + p.height) - rect.y) < epsilon && 
                        Math.abs(p.x - rect.x) < epsilon
                    );

                    if (neighbor) {
                        const neighborPart = this.parts.find(p => p.id === neighbor.item.partId);
                        const w = rotation === 90 ? item.rotatedWidth : item.width;
                        if (Math.abs(neighbor.width - w) < epsilon && neighborPart) {

                            const gap = this.solveCommonLineGap(
                                neighborPart, neighbor.rotation, 'top',
                                candPart, rotation, 'bottom'
                            );

                            if (gap !== null) sY = gap;
                        }
                    }
                }
            }
        }

        return { x: sX, y: sY };
    }

    private solveCommonLineGap(
        pA: Part, rotA: number, edgeA: 'right' | 'top',
        pB: Part, rotB: number, edgeB: 'left' | 'bottom'
    ): number | null {
        // Get relevant punches on the interface edges
        // A is Neighbor (Left/Top), B is Candidate (Right/Bottom)

        const getEdgeTool = (part: Part, rot: number, edge: 'left'|'right'|'top'|'bottom') => {
            // Normalize punch coords to World Space (assuming part at 0,0) based on rotation
            // We want the punch relative to the bounding box face.
            const w = part.geometry.width;
            const h = part.geometry.height;
            const tools = this.tools;

            let matches: { toolId: string, edgeOffset: number, rotation: number }[] = [];

            part.punches.forEach(p => {
                // Transform P to World (Part @ 0,0)
                let wx = p.x; 
                let wy = p.y;
                let dimX = w;
                let dimY = h;

                if (rot === 90) {
                    wx = -p.y + h; // 90 deg rotation transform mapping x->y axis roughly
                    wy = p.x;
                    dimX = h;
                    dimY = w;
                }

                // Check distance to requested edge
                const tool = tools.find(t => t.id === p.toolId);
                if (!tool) return;
                const r = tool.width / 2; // Assume symmetric or use logic

                let dist = Infinity;
                let offset = 0; // Positive = Inside part, Negative = Outside

                if (edge === 'right') { // x = dimX
                    dist = Math.abs(wx - dimX);
                    offset = wx - dimX; 
                } else if (edge === 'left') { // x = 0
                    dist = Math.abs(wx - 0);
                    offset = wx;
                } else if (edge === 'top') { // y = dimY
                    dist = Math.abs(wy - dimY);
                    offset = wy - dimY;
                } else if (edge === 'bottom') { // y = 0
                    dist = Math.abs(wy - 0);
                    offset = wy;
                }

                if (dist < (r + 1.0)) { // Within 1mm of edge + radius
                    matches.push({ toolId: p.toolId, edgeOffset: offset, rotation: p.rotation });
                }
            });

            // Prioritize rectangular tools for common cuts
            matches.sort((a,b) => a.edgeOffset - b.edgeOffset); // Just pick first for now
            return matches.length > 0 ? matches[0] : null;
        };

        const tA = getEdgeTool(pA, rotA, edgeA);
        const tB = getEdgeTool(pB, rotB, edgeB);

        if (tA && tB && tA.toolId === tB.toolId) {
            // Found matching tool used on both edges!
            const tool = this.tools.find(t => t.id === tA.toolId);
            if (!tool) return null;

            // Calculate the effective dimension of the tool in the direction of separation (perpendicular to cut)
            // This ensures we get the "Height" of the tool relative to the cut, to overlap fully.

            // Total Rotation relative to the nest = Part Rotation + Punch Rotation
            // (We use tA because we want the dimension of the tool as it cuts the edge of A)
            const totalRot = (rotA + tA.rotation) % 360;
            const rad = totalRot * Math.PI / 180;

            let tW = tool.width;
            let tH = tool.height;
            if (tool.shape === ToolShape.Circle) tH = tW;

            const absCos = Math.abs(Math.cos(rad));
            const absSin = Math.abs(Math.sin(rad));

            // Effective BBox of tool
            const effW = tW * absCos + tH * absSin;
            const effH = tW * absSin + tH * absCos;

            // Determine which dimension is the "separation" dimension
            // If cutting vertical line (edge Left/Right), we separate in X. We need X dimension.
            if (edgeA === 'right') {
                return -effW; // Negative Tool Width
            } else {
                // If cutting horizontal line (edge Top/Bottom), we separate in Y. We need Y dimension.
                return -effH; // Negative Tool Height
            }
        }

        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, sX: number, sY: number) {
        const freeRect = this.freeRects[rectIndex];

        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        // Position: FreeRect start + spacing
        const placedX = freeRect.x + sX;
        const placedY = freeRect.y + sY;

        // Add to placed list
        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            width: w,
            height: h,
            rotation
        });

        // "Used" Rectangle includes the spacing gap we consumed.
        // It starts at the FreeRect origin and extends to cover the part.
        const usedRect: FreeRect = {
            x: freeRect.x,
            y: freeRect.y,
            w: sX + w, // Consumes gap + part width
            h: sY + h  // Consumes gap + part height
        };

        // --- MAXRECTS SPLIT & PRUNE ---

        const newFreeRects: FreeRect[] = [];

        for (let i = 0; i < this.freeRects.length; i++) {
            const existing = this.freeRects[i];

            if (this.intersects(existing, usedRect)) {
                // Top
                if (usedRect.y > existing.y && usedRect.y < existing.y + existing.h) {
                    newFreeRects.push({
                        x: existing.x,
                        y: existing.y,
                        w: existing.w,
                        h: usedRect.y - existing.y
                    });
                }
                // Bottom
                if (usedRect.y + usedRect.h < existing.y + existing.h) {
                    newFreeRects.push({
                        x: existing.x,
                        y: usedRect.y + usedRect.h,
                        w: existing.w,
                        h: (existing.y + existing.h) - (usedRect.y + usedRect.h)
                    });
                }
                // Left
                if (usedRect.x > existing.x && usedRect.x < existing.x + existing.w) {
                    newFreeRects.push({
                        x: existing.x,
                        y: existing.y,
                        w: usedRect.x - existing.x,
                        h: existing.h
                    });
                }
                // Right
                if (usedRect.x + usedRect.w < existing.x + existing.w) {
                    newFreeRects.push({
                        x: usedRect.x + usedRect.w,
                        y: existing.y,
                        w: (existing.x + existing.w) - (usedRect.x + usedRect.w),
                        h: existing.h
                    });
                }
            } else {
                newFreeRects.push(existing);
            }
        }

        this.freeRects = newFreeRects;
        this.pruneFreeRects();
    }

    private intersects(a: FreeRect, b: FreeRect): boolean {
        return a.x < b.x + b.w && a.x + a.w > b.x &&
               a.y < b.y + b.h && a.y + a.h > b.y;
    }

    private pruneFreeRects() {
        this.freeRects = this.freeRects.filter(r => r.w > 0.5 && r.h > 0.5);

        for (let i = 0; i < this.freeRects.length; i++) {
            for (let j = 0; j < this.freeRects.length; j++) {
                if (i === j) continue;
                if (this.isContained(this.freeRects[i], this.freeRects[j])) {
                    this.freeRects.splice(i, 1);
                    i--; 
                    break; 
                }
            }
        }
    }

    private isContained(inner: FreeRect, outer: FreeRect): boolean {
        return inner.x >= outer.x && inner.y >= outer.y &&
               inner.x + inner.w <= outer.x + outer.w &&
               inner.y + inner.h <= outer.y + outer.h;
    }
}

// ----------------------------------------------------------------------
// ADAPTIVE GROUPING LOGIC
// ----------------------------------------------------------------------

const getGroupPriorityScore = (group: PriorityGroup): number => {
    switch (group) {
        case PriorityGroup.BigLong: return 4000;
        case PriorityGroup.SmallLong: return 3000;
        case PriorityGroup.BigSquare: return 2000;
        case PriorityGroup.SmallSquare: return 1000;
        default: return 0;
    }
};

const classifyItems = (items: PackerItem[]): { classifications: Map<string, PriorityGroup>, counts: Record<PriorityGroup, number>, medianArea: number } => {
    if (items.length === 0) return { classifications: new Map(), counts: {0:0,1:0,2:0,3:0,99:0} as any, medianArea: 0 };

    const areas = items.map(i => i.area).sort((a,b) => a - b);
    const mid = Math.floor(areas.length / 2);
    const medianArea = areas.length % 2 !== 0 ? areas[mid] : (areas[mid - 1] + areas[mid]) / 2;

    const classifications = new Map<string, PriorityGroup>();
    const counts: Record<PriorityGroup, number> = {
        [PriorityGroup.BigLong]: 0,
        [PriorityGroup.SmallLong]: 0,
        [PriorityGroup.BigSquare]: 0,
        [PriorityGroup.SmallSquare]: 0,
        [PriorityGroup.Unknown]: 0
    };

    items.forEach(item => {
        const isBig = item.area >= medianArea;
        const isLong = item.aspectRatio >= 1.5;

        let group: PriorityGroup;
        if (isBig && isLong) group = PriorityGroup.BigLong;
        else if (!isBig && isLong) group = PriorityGroup.SmallLong;
        else if (isBig && !isLong) group = PriorityGroup.BigSquare;
        else group = PriorityGroup.SmallSquare;

        classifications.set(item.uid, group);
        counts[group]++;
    });

    return { classifications, counts, medianArea };
};

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    const orientationPreferences = new Map<string, number>();

    const stockSheet = settings.availableSheets.find(s => s.id === settings.activeSheetId) || settings.availableSheets[0];
    const simW = stockSheet ? stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight : 2500;
    const simH = stockSheet ? stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom : 1250;

    const uniquePartIds = Array.from(new Set(scheduledParts.map(sp => sp.partId)));

    for (const pid of uniquePartIds) {
        const part = allParts.find(p => p.id === pid);
        const sched = scheduledParts.find(sp => sp.partId === pid);
        if (part && sched) {
            const dims = calculatePartPhysicalExtents(part, tools);
            const pref = determineOptimalOrientation(
                dims.width, dims.height, 
                simW, simH, 
                settings.partSpacingX, settings.partSpacingY,
                sched.nesting.allow90_270
            );
            if (pref !== undefined) {
                orientationPreferences.set(pid, pref);
            }
        }
    }

    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        const preferredRot = orientationPreferences.get(sp.partId);

        const maxDim = Math.max(dims0.width, dims0.height);
        const minDim = Math.min(dims0.width, dims0.height);
        const aspectRatio = minDim > 0 ? maxDim / minDim : 1;

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                hasCommonLine: sp.nesting.commonLine, // Propagate setting to item
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX,
                area: dims0.width * dims0.height,
                preferredRotation: preferredRot,
                aspectRatio
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    const calculateEfficiency = (packer: MaxRectsPacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    while (remainingItems.length > 0) {

        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        const { classifications, counts, medianArea } = classifyItems(remainingItems);

        // Update items with their current classification group
        remainingItems.forEach(item => {
            item.currentGroup = classifications.get(item.uid);
        });

        const totalRemaining = remainingItems.length;
        const hasBigItems = (counts[PriorityGroup.BigLong] + counts[PriorityGroup.BigSquare]) > 0;

        const strategies: { name: string, packer: MaxRectsPacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Priority-Adaptive', sort: 'weighted_group' },
            { id: 'BestFit-Area', sort: 'area' },
            { id: 'MaxSide', sort: 'max_side' },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            currentItems.sort((a, b) => {
                if (config.sort === 'weighted_group') {
                    const groupA = classifications.get(a.uid) ?? PriorityGroup.Unknown;
                    const baseA = getGroupPriorityScore(groupA);
                    const ratioA = totalRemaining > 0 ? counts[groupA] / totalRemaining : 0;
                    const bonusA = ratioA * 500;
                    // INCREASE PRIORITY FOR COMMON LINE ITEMS
                    const scoreA = baseA + bonusA + (a.hasCommonLine ? 5000 : 0);

                    const groupB = classifications.get(b.uid) ?? PriorityGroup.Unknown;
                    const baseB = getGroupPriorityScore(groupB);
                    const ratioB = totalRemaining > 0 ? counts[groupB] / totalRemaining : 0;
                    const bonusB = ratioB * 500;
                    // INCREASE PRIORITY FOR COMMON LINE ITEMS
                    const scoreB = baseB + bonusB + (b.hasCommonLine ? 5000 : 0);

                    if (Math.abs(scoreA - scoreB) > 1) {
                        return scoreB - scoreA;
                    }
                    return b.area - a.area;
                }

                if (config.sort === 'width') return b.width - a.width;
                if (config.sort === 'max_side') return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                return b.area - a.area;
            });

            if (hasBigItems && config.sort === 'weighted_group') {
                // If the top item isn't common line, check if we need to pull big items.
                // If top item IS common line (score > 5000), leave it.
                if (!currentItems[0].hasCommonLine) {
                    const firstBigIndex = currentItems.findIndex(item => {
                        const g = classifications.get(item.uid);
                        return g === PriorityGroup.BigLong || g === PriorityGroup.BigSquare;
                    });

                    if (firstBigIndex > 0) {
                        const bigItem = currentItems[firstBigIndex];
                        currentItems.splice(firstBigIndex, 1);
                        currentItems.unshift(bigItem);
                    }
                }
            }

            // Pass Parts and Tools to Packer
            const packer = new MaxRectsPacker(packW, packH, partSpacingX, partSpacingY, useCommonLine, allParts, tools);
            const packedUids = new Set<string>();

            for (const item of currentItems) {
                const bestPos = packer.findPosition(item);
                if (bestPos) {
                    packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.sX, bestPos.sY);
                    packedUids.add(item.uid);
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            let score = count * 1000 + efficiency * 100;
            if (config.id === 'Priority-Adaptive') score += 50; 

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        const templateParts = winner.packer.placedItems;
        const requiredParts = new Map<string, number>();
        templateParts.forEach(p => {
            requiredParts.set(p.item.partId, (requiredParts.get(p.item.partId) || 0) + 1);
        });

        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        let sheetQuantity = 1;

        while (true) {
            const indicesToRemove: number[] = [];
            const tempUsedIndices = new Set<number>();
            let possible = true;

            for (const [partId, reqQty] of requiredParts.entries()) {
                let found = 0;
                for (let i = 0; i < remainingItems.length; i++) {
                    if (tempUsedIndices.has(i)) continue;
                    if (remainingItems[i].partId === partId) {
                        tempUsedIndices.add(i);
                        indicesToRemove.push(i);
                        found++;
                        if (found === reqQty) break;
                    }
                }
                if (found < reqQty) { possible = false; break; }
            }

            if (possible) {
                sheetQuantity++;
                indicesToRemove.sort((a, b) => b - a);
                indicesToRemove.forEach(idx => remainingItems.splice(idx, 1));
            } else {
                break;
            }
        }

        const packer = winner.packer;

        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = p.width; // Already resolved in placedItems
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1} (${winner.name})`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: sheetQuantity
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}
